// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public boolean isSameTree(TreeNode p, TreeNode q) {
    if (p == null && q == null) return true;    // both empty → match
    if (p == null || q == null) return false;   // exactly one empty → differ
    return p.val == q.val                        // values must match
        && isSameTree(p.left, q.left)            // left subtrees match
        && isSameTree(p.right, q.right);         // right subtrees match
}

public boolean isSameTree(TreeNode p, TreeNode q) {
    Deque<TreeNode[]> stack = new ArrayDeque<>();
    stack.push(new TreeNode[]{p, q});
    while (!stack.isEmpty()) {
        TreeNode[] pair = stack.pop();
        TreeNode a = pair[0], b = pair[1];
        if (a == null && b == null) continue;       // consistent empty
        if (a == null || b == null) return false;    // structural mismatch
        if (a.val != b.val) return false;            // value mismatch
        stack.push(new TreeNode[]{a.left, b.left});
        stack.push(new TreeNode[]{a.right, b.right});
    }
    return true;
}

